/**
* Generates the portable index.html for each deployment target.
* ALL file links are in the main directory (./favicon.svg, ./fonts.css, ./style.css, ./app.js)
* with ZERO root (/) references so the app works immediately in any main branch,
* repository subpath, Netlify drop, Google Sites iframe, or local folder.
*/
function buildPortableIndexHtml(target, initialDataJsonStr) {
	const isGoogleSitesEmbed = target === "google-sites-embed";
	const title = isGoogleSitesEmbed ? "SiteTrack Pro — Embed-Ready Construction & Contract TCP Ledger" : "SiteTrack Pro — Real-Time Project & Sub-Project Monitor";
	const safeInlineDataScript = initialDataJsonStr ? `    <script>window.__SITETRACK_INITIAL_DATA__ = ${initialDataJsonStr.replace(/<\/script/gi, "<\\/script")};<\/script>\n` : "";
	return `<!doctype html>
<html lang="en" data-deploy-target="${target}"${isGoogleSitesEmbed ? " data-embed-mode=\"google-sites\"" : ""}>
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>${title}</title>
    <meta name="description" content="Self-contained construction project status tracker, sub-project TCP contract manager, BIR tax calculator, and printable ledger dashboard." />
    <meta property="og:title" content="${title}" />
    <meta property="og:description" content="Self-contained construction project status tracker, sub-project TCP contract manager, BIR tax calculator, and printable ledger dashboard." />
    <meta property="og:type" content="website" />
    <meta name="twitter:card" content="summary_large_image" />
    <link rel="icon" type="image/svg+xml" href="./favicon.svg" />
    <link rel="stylesheet" href="./fonts.css" />
    <link rel="stylesheet" href="./style.css" />
  </head>
  <body>
    <div id="root"></div>
${safeInlineDataScript}    <script defer src="./app.js"><\/script>
  </body>
</html>
`;
}
/**
* Wraps the compiled JS in a self-invoking IIFE so it runs cleanly via <script defer src="./app.js"><\/script>
* across all static servers (GitHub Pages, Netlify, Google Sites) and local file:// environments.
*/
function wrapPortableJsBundle(rawJs) {
	if (rawJs.trim().startsWith("(function(){")) return rawJs;
	return `(function(){\n"use strict";\n${rawJs}\n})();\n`;
}
/**
* Generates netlify.toml for Netlify and Google Sites Embed hosting.
*/
function buildPortableNetlifyToml(target) {
	return `# netlify.toml — Static Deployment Configuration for SiteTrack Pro (${target})
# No build command required: all HTML, CSS, JS, images, fonts, and JSON data are pre-built in the main directory.

[build]
  publish = "."

# SPA Fallback Routing (Relative to main publish directory)
[[redirects]]
  from = "/*"
  to = "./index.html"
  status = 200

# Security & Iframe Embedding Headers (Supports Google Sites Embed URL & OAuth Popups)
[[headers]]
  for = "/*"
  [headers.values]
    Content-Security-Policy = "frame-ancestors 'self' https://sites.google.com https://*.google.com https://*.googleusercontent.com *;"
    Cross-Origin-Opener-Policy = "same-origin-allow-popups"
    Referrer-Policy = "strict-origin-when-cross-origin"
`;
}
